WITH valid_shipments AS (SELECT * FROM shipments WHERE order_id = 26 AND carrier IN ('Flash', 'UPS', 'Kerry')), status_summary AS (SELECT status, order_id, MAX(cost) AS max_cost, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(carrier))) AS carrier_values FROM valid_shipments GROUP BY status, order_id) SELECT status, order_id, max_cost, carrier_values FROM status_summary WHERE max_cost > 29 ORDER BY carrier_values, status, order_id LIMIT 50
